<template>
  <div class="mission-progress">
    <div class="mission-progress__header">
      <span class="mission-progress__label">{{ label || $t('docnet_progress') }}</span>
      <span class="mission-progress__value">{{ percent }}%</span>
    </div>
    <div class="mission-progress__track">
      <div
        v-for="(seg, idx) in segments"
        :key="idx"
        class="mission-progress__segment"
        :style="{ width: seg.percent + '%', background: seg.color }"
      />
    </div>
    <div v-if="!hideLegend && legendSegments.length > 0" class="mission-progress__legend">
      <span
        v-for="(seg, idx) in legendSegments"
        :key="idx"
        class="mission-progress__legend-item"
      >
        <span class="mission-progress__legend-dot" :style="{ background: seg.color }" />
        {{ seg.label }} ({{ seg.count }})
      </span>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent, type PropType } from 'vue';
import { statusLabel } from '../../shared/docnet-labels';

export interface StatusBreakdown {
  status: string;
  count: number;
  hideLegend?: boolean;
}

const STATUS_COLORS: Record<string, string> = {
  done: '#21ba45',
  completed: '#21ba45',
  in_progress: '#1976d2',
  in_review: '#f2c037',
  todo: '#26a69a',
  open: '#90a4ae',
  backlog: '#78909c',
  error: '#c10015',
  cancelled: '#9e9e9e',
};

const STATUS_LABEL_KEYS: Record<string, string> = {
  done: 'docnet_mission_status_done',
  completed: 'docnet_mission_status_completed',
  in_progress: 'docnet_mission_status_in_progress',
  in_review: 'docnet_mission_status_in_review',
  todo: 'docnet_mission_status_todo',
  open: 'docnet_mission_status_open',
  backlog: 'docnet_mission_status_backlog',
  error: 'docnet_mission_status_error',
  cancelled: 'docnet_mission_status_cancelled',
};

// Order for display (done first, then active, then waiting)
const STATUS_ORDER: string[] = [
  'done', 'completed', 'in_progress', 'in_review', 'todo', 'open', 'backlog', 'error', 'cancelled',
];

export default defineComponent({
  name: 'MissionProgressBar',
  props: {
    percent: {
      type: Number,
      default: 0,
    },
    label: {
      type: String,
      default: '',
    },
    statusBreakdown: {
      type: Array as PropType<StatusBreakdown[]>,
      default: () => [],
    },
    hideLegend: {
      type: Boolean,
      default: false,
    },
  },
  computed: {
    legendSegments(): Array<{ percent: number; color: string; label: string; count: number }> {
      return this.segments.filter((s) => !s.hideLegend);
    },

    segments(): Array<{ percent: number; color: string; label: string; count: number; hideLegend?: boolean }> {
      if (!this.statusBreakdown.length) {
        // Fallback: single bar like before
        if (this.percent <= 0) return [];
        return [{ percent: this.percent, color: this.fillColor, label: '', count: 0 }];
      }

      const total = this.statusBreakdown.reduce((sum, s) => sum + s.count, 0);
      if (total === 0) return [];

      // Sort by defined order; hideLegend entries (mission) always last
      const sorted = [...this.statusBreakdown]
        .filter((s) => s.count > 0)
        .sort((a, b) => {
          if (a.hideLegend && !b.hideLegend) return 1;
          if (!a.hideLegend && b.hideLegend) return -1;
          const ai = STATUS_ORDER.indexOf(a.status);
          const bi = STATUS_ORDER.indexOf(b.status);
          return (ai === -1 ? 99 : ai) - (bi === -1 ? 99 : bi);
        });

      return sorted.map((s) => ({
        percent: (s.count / total) * 100,
        color: STATUS_COLORS[s.status] || '#9e9e9e',
        label: STATUS_LABEL_KEYS[s.status]
          ? (this.$t(STATUS_LABEL_KEYS[s.status]) as string)
          : statusLabel(this.$t, s.status || ''),
        count: s.count,
        hideLegend: s.hideLegend || false,
      }));
    },

    fillColor(): string {
      if (this.percent >= 100) return '#21ba45';
      if (this.percent >= 60) return '#1976d2';
      if (this.percent >= 30) return '#f2c037';
      return '#c10015';
    },
  },
});
</script>

